source = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    row_bars = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_bars = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_edges = [-1] + row_bars + [h]
    col_edges = [-1] + col_bars + [w]
    row_ranges = [(row_edges[i] + 1, row_edges[i + 1]) for i in range(len(row_edges) - 1)]
    col_ranges = [(col_edges[i] + 1, col_edges[i + 1]) for i in range(len(col_edges) - 1)]
    out = [row[:] for row in grid]
    tiles = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color not in (0, 8):
                tr = next(i for i, (a, b) in enumerate(row_ranges) if a <= r < b)
                tc = next(i for i, (a, b) in enumerate(col_ranges) if a <= c < b)
                tiles.setdefault(color, []).append((tr, tc))
    painted = {}
    for color, points in tiles.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2:
                    for tc in range(min(c1, c2), max(c1, c2) + 1):
                        painted.setdefault((r1, tc), set()).add(color)
                if c1 == c2:
                    for tr in range(min(r1, r2), max(r1, r2) + 1):
                        painted.setdefault((tr, c1), set()).add(color)
    for (tr, tc), colors in painted.items():
        color = next(iter(colors)) if len(colors) == 1 else 6
        ra, rb = row_ranges[tr]
        ca, cb = col_ranges[tc]
        for r in range(ra, rb):
            for c in range(ca, cb):
                out[r][c] = color
    return out
'''
